$pdo->exec("USE `$target`");$docs=$pdo->query('SELECT storage_key,sha256_hash FROM documents')->fetchAll(PDO::FETCH_ASSOC);foreach($docs as $doc){$p=$dir.'/storage/'.$doc['storage_key'];if(!is_file($p)||!hash_equals($doc['sha256_hash'],hash_file('sha256',$p)))throw new RuntimeException('Restored document integrity failed.');}
